//! The opening and interaction sounds. The clips (generated by
//! scripts/gen-sounds.py) are decoded once at start and mixed on one thread
//! into a PulseAudio simple-API stream, which PipeWire provides. libpulse-simple
//! is loaded at run time, so without it Keymap still works, silently. The
//! thread sleeps between sounds; the stream closes after 2 s of silence.

use std::ffi::{CStr, c_char, c_int, c_void};
use std::sync::Arc;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::mpsc::{self, Receiver, RecvTimeoutError, Sender, TryRecvError};
use std::time::Duration;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Cue {
    /// The first opening's ripple (~1.47 s).
    First,
    /// Later openings (~0.73 s): same sound, shorter envelopes, same pitch.
    Later,
    /// Motion off: a short, quiet equivalent.
    Quick,
    /// A key was selected: a soft ~45 ms tick.
    Select,
    /// A key was deselected: the same tick, a little lower.
    Deselect,
    /// A binding change was saved: a gentle ~150 ms tone.
    Saved,
}

impl Cue {
    fn is_tick(self) -> bool {
        matches!(self, Cue::Select | Cue::Deselect)
    }
}

enum Msg {
    Play(Cue),
    Stop,
}

pub struct Sound {
    tx: Sender<Msg>,
    gain: Arc<AtomicU32>,
}

const RATE: u32 = 48_000;
/// Samples written per step (10 ms); between steps the player checks for
/// stop/replace requests.
const CHUNK: usize = 480;
/// Fade-out when a sound is cut short (30 ms).
const FADE: usize = 1_440;
/// A tick within 35 ms of the previous one is skipped: rapid clicks never
/// stack up or queue.
const TICK_GAP: usize = 1_680;
/// At most this many sounds overlap (the rest are fading out).
const MAX_VOICES: usize = 4;
/// Silence after which the stream is closed, letting the device suspend.
const IDLE: Duration = Duration::from_secs(2);
/// Audio kept queued in the server (20 ms): small, so stopping is prompt.
const TARGET_BYTES: u32 = 1_920;

impl Sound {
    pub fn start(volume: f64) -> Sound {
        let (tx, rx) = mpsc::channel();
        let gain = Arc::new(AtomicU32::new(gain_for(volume).to_bits()));
        let g = gain.clone();
        if let Err(e) = std::thread::Builder::new().name("keymap-sound".into()).spawn(move || run(rx, g)) {
            crate::ui::trace(&format!("sound: no player thread: {e}"));
        }
        Sound { tx, gain }
    }

    /// Play `cue`. A tick fades out an earlier tick (or is skipped if one
    /// just started); other cues fade out whatever is playing.
    pub fn play(&self, cue: Cue) {
        self.tx.send(Msg::Play(cue)).ok();
    }

    /// Fade out the current sound, if any.
    pub fn stop(&self) {
        self.tx.send(Msg::Stop).ok();
    }

    pub fn set_volume(&self, volume: f64) {
        self.gain.store(gain_for(volume).to_bits(), Ordering::Relaxed);
    }
}

/// Volume slider (0–1) to linear gain; squared so the slider feels even.
fn gain_for(volume: f64) -> f32 {
    (volume.clamp(0.0, 1.0) as f32).powi(2)
}

/// A clip being played, possibly fading out.
struct Voice {
    cue: Cue,
    pos: usize,
    fade: Option<usize>,
}

fn run(rx: Receiver<Msg>, gain: Arc<AtomicU32>) {
    let clips = [
        decode(include_bytes!("../assets/sounds/ripple-first.wav")),
        decode(include_bytes!("../assets/sounds/ripple-later.wav")),
        decode(include_bytes!("../assets/sounds/open-quick.wav")),
        decode(include_bytes!("../assets/sounds/select.wav")),
        decode(include_bytes!("../assets/sounds/deselect.wav")),
        decode(include_bytes!("../assets/sounds/saved.wav")),
    ];
    let pulse = Pulse::load();
    if pulse.is_none() {
        crate::ui::trace("sound: libpulse-simple unavailable; sounds are off");
    }
    let mut voices: Vec<Voice> = Vec::new();
    let mut stream: Option<Stream> = None;
    let mut mix = vec![0f32; CHUNK];
    let mut out: Vec<i16> = Vec::with_capacity(CHUNK);
    loop {
        if voices.is_empty() {
            // Silent: sleep until a message (closing an idle stream first).
            let msg = if stream.is_some() {
                match rx.recv_timeout(IDLE) {
                    Ok(m) => m,
                    Err(RecvTimeoutError::Timeout) => {
                        stream = None;
                        continue;
                    }
                    Err(RecvTimeoutError::Disconnected) => return,
                }
            } else {
                match rx.recv() {
                    Ok(m) => m,
                    Err(_) => return,
                }
            };
            handle(msg, &mut voices, &clips);
        }
        loop {
            match rx.try_recv() {
                Ok(m) => handle(m, &mut voices, &clips),
                Err(TryRecvError::Empty) => break,
                Err(TryRecvError::Disconnected) => return,
            }
        }
        if voices.is_empty() {
            continue;
        }
        let Some(p) = &pulse else {
            voices.clear();
            continue;
        };
        if stream.is_none() {
            stream = p.open();
            if stream.is_none() {
                voices.clear();
                continue;
            }
        }
        mix_chunk(&mut voices, &clips, &mut mix);
        let g = f32::from_bits(gain.load(Ordering::Relaxed));
        out.clear();
        out.extend(mix.iter().map(|&x| (x * g).clamp(-32768.0, 32767.0) as i16));
        // Blocks only while the server holds TARGET_BYTES, which paces the loop.
        if stream.as_ref().is_some_and(|s| !s.write(&out)) {
            stream = None;
            voices.clear();
        }
    }
}

fn handle(msg: Msg, voices: &mut Vec<Voice>, clips: &[Vec<i16>]) {
    let fade = |v: &mut Voice| {
        v.fade.get_or_insert(FADE);
    };
    match msg {
        Msg::Stop => voices.iter_mut().for_each(fade),
        Msg::Play(cue) => {
            if clips[cue as usize].is_empty() {
                return;
            }
            if cue.is_tick() {
                if voices.iter().any(|v| v.cue.is_tick() && v.fade.is_none() && v.pos < TICK_GAP) {
                    return;
                }
                voices.iter_mut().filter(|v| v.cue.is_tick()).for_each(fade);
            } else {
                voices.iter_mut().for_each(fade);
            }
            if voices.len() >= MAX_VOICES {
                voices.remove(0);
            }
            voices.push(Voice { cue, pos: 0, fade: None });
        }
    }
}

/// Mix the next 10 ms of every voice into `mix`, dropping finished voices.
fn mix_chunk(voices: &mut Vec<Voice>, clips: &[Vec<i16>], mix: &mut [f32]) {
    mix.fill(0.0);
    for v in voices.iter_mut() {
        let clip = &clips[v.cue as usize];
        for m in mix.iter_mut() {
            if v.pos >= clip.len() || v.fade == Some(0) {
                break;
            }
            let mut x = clip[v.pos] as f32;
            if let Some(f) = v.fade.as_mut() {
                x *= *f as f32 / FADE as f32;
                *f -= 1;
            }
            *m += x;
            v.pos += 1;
        }
    }
    voices.retain(|v| v.pos < clips[v.cue as usize].len() && v.fade != Some(0));
}

/// Samples of a 48 kHz mono 16-bit PCM WAV; empty for anything else.
fn decode(wav: &[u8]) -> Vec<i16> {
    let u16_at = |i: usize| wav.get(i..i + 2).map(|b| u16::from_le_bytes([b[0], b[1]]));
    let u32_at = |i: usize| wav.get(i..i + 4).map(|b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]));
    if wav.get(0..4) != Some(b"RIFF") || wav.get(8..12) != Some(b"WAVE") {
        return Vec::new();
    }
    let (mut i, mut format_ok) = (12, false);
    while let (Some(id), Some(len)) = (wav.get(i..i + 4), u32_at(i + 4)) {
        let body = i + 8;
        let len = len as usize;
        match id {
            b"fmt " => {
                format_ok = u16_at(body) == Some(1)
                    && u16_at(body + 2) == Some(1)
                    && u32_at(body + 4) == Some(RATE)
                    && u16_at(body + 14) == Some(16)
            }
            b"data" if format_ok => {
                let data = wav.get(body..(body + len).min(wav.len())).unwrap_or_default();
                return data.as_chunks::<2>().0.iter().map(|&b| i16::from_le_bytes(b)).collect();
            }
            _ => {}
        }
        i = body + len + (len & 1);
    }
    Vec::new()
}

#[repr(C)]
struct SampleSpec {
    format: c_int,
    rate: u32,
    channels: u8,
}

#[repr(C)]
struct BufferAttr {
    maxlength: u32,
    tlength: u32,
    prebuf: u32,
    minreq: u32,
    fragsize: u32,
}

type NewFn = unsafe extern "C" fn(
    *const c_char,
    *const c_char,
    c_int,
    *const c_char,
    *const c_char,
    *const SampleSpec,
    *const c_void,
    *const BufferAttr,
    *mut c_int,
) -> *mut c_void;
type WriteFn = unsafe extern "C" fn(*mut c_void, *const c_void, usize, *mut c_int) -> c_int;
type DrainFn = unsafe extern "C" fn(*mut c_void, *mut c_int) -> c_int;
type FreeFn = unsafe extern "C" fn(*mut c_void);

const PA_STREAM_PLAYBACK: c_int = 1;
const PA_SAMPLE_S16LE: c_int = 3;

struct Pulse {
    new: NewFn,
    write: WriteFn,
    drain: DrainFn,
    free: FreeFn,
}

impl Pulse {
    fn load() -> Option<Pulse> {
        // SAFETY: dlopen/dlsym with valid C strings; each symbol is cast to the
        // signature documented in <pulse/simple.h>. The library stays loaded
        // for the life of the process.
        unsafe {
            let lib = libc::dlopen(c"libpulse-simple.so.0".as_ptr(), libc::RTLD_NOW | libc::RTLD_LOCAL);
            if lib.is_null() {
                return None;
            }
            let sym = |name: &CStr| {
                let p = libc::dlsym(lib, name.as_ptr());
                (!p.is_null()).then_some(p)
            };
            Some(Pulse {
                new: std::mem::transmute::<*mut c_void, NewFn>(sym(c"pa_simple_new")?),
                write: std::mem::transmute::<*mut c_void, WriteFn>(sym(c"pa_simple_write")?),
                drain: std::mem::transmute::<*mut c_void, DrainFn>(sym(c"pa_simple_drain")?),
                free: std::mem::transmute::<*mut c_void, FreeFn>(sym(c"pa_simple_free")?),
            })
        }
    }

    fn open(&self) -> Option<Stream<'_>> {
        let spec = SampleSpec { format: PA_SAMPLE_S16LE, rate: RATE, channels: 1 };
        let attr = BufferAttr { maxlength: u32::MAX, tlength: TARGET_BYTES, prebuf: u32::MAX, minreq: u32::MAX, fragsize: u32::MAX };
        let mut err = 0;
        // SAFETY: valid strings and structs that outlive the call.
        let s = unsafe {
            (self.new)(
                std::ptr::null(),
                c"Keymap".as_ptr(),
                PA_STREAM_PLAYBACK,
                std::ptr::null(),
                c"Keymap sounds".as_ptr(),
                &spec,
                std::ptr::null(),
                &attr,
                &mut err,
            )
        };
        if s.is_null() {
            crate::ui::trace(&format!("sound: cannot open a playback stream (error {err})"));
            return None;
        }
        Some(Stream { pulse: self, s })
    }
}

/// An open playback stream; dropping it plays out what is queued and closes it.
struct Stream<'a> {
    pulse: &'a Pulse,
    s: *mut c_void,
}

impl Stream<'_> {
    fn write(&self, samples: &[i16]) -> bool {
        let mut err = 0;
        // SAFETY: `samples` is valid for its length in bytes; `s` is open.
        unsafe { (self.pulse.write)(self.s, samples.as_ptr().cast(), samples.len() * 2, &mut err) >= 0 }
    }
}

impl Drop for Stream<'_> {
    fn drop(&mut self) {
        let mut err = 0;
        // SAFETY: `s` came from pa_simple_new and is freed exactly once.
        unsafe {
            (self.pulse.drain)(self.s, &mut err);
            (self.pulse.free)(self.s);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bundled_clips_decode_with_the_ripple_lengths() {
        let secs = |b: &[u8]| decode(b).len() as f64 / RATE as f64;
        let first = secs(include_bytes!("../assets/sounds/ripple-first.wav"));
        let later = secs(include_bytes!("../assets/sounds/ripple-later.wav"));
        assert!((first - keymap::motion::FIRST_OPEN_SECS).abs() < 0.005, "{first}");
        assert!((later - keymap::motion::LATER_OPEN_SECS).abs() < 0.005, "{later}");
        assert!(secs(include_bytes!("../assets/sounds/open-quick.wav")) < 0.25);
        for tick in [&include_bytes!("../assets/sounds/select.wav")[..], include_bytes!("../assets/sounds/deselect.wav")] {
            assert!((0.03..=0.06).contains(&secs(tick)));
        }
        assert!((0.1..=0.18).contains(&secs(include_bytes!("../assets/sounds/saved.wav"))));
    }

    fn clips() -> Vec<Vec<i16>> {
        // Six clips indexed by `Cue`, each 100 ms of a constant level.
        vec![vec![1000; 4800]; 6]
    }

    #[test]
    fn rapid_ticks_are_skipped_not_queued() {
        let c = clips();
        let mut v = Vec::new();
        handle(Msg::Play(Cue::Select), &mut v, &c);
        handle(Msg::Play(Cue::Deselect), &mut v, &c);
        assert_eq!(v.len(), 1, "a tick right after a tick is skipped");
        v[0].pos = TICK_GAP;
        handle(Msg::Play(Cue::Deselect), &mut v, &c);
        assert_eq!(v.len(), 2);
        assert_eq!(v[0].fade, Some(FADE), "the earlier tick fades out");
        assert!(v[1].fade.is_none());
        for _ in 0..20 {
            v.last_mut().unwrap().pos = TICK_GAP;
            handle(Msg::Play(Cue::Select), &mut v, &c);
        }
        assert!(v.len() <= MAX_VOICES);
    }

    #[test]
    fn a_tick_during_the_opening_sound_plays_at_once() {
        let c = clips();
        let mut v = Vec::new();
        handle(Msg::Play(Cue::Later), &mut v, &c);
        // Clicking a key during the ripple: the ripple stops the sound, then the tick plays.
        handle(Msg::Stop, &mut v, &c);
        handle(Msg::Play(Cue::Select), &mut v, &c);
        assert_eq!(v.len(), 2);
        assert_eq!((v[0].cue, v[0].fade), (Cue::Later, Some(FADE)));
        assert_eq!((v[1].cue, v[1].fade), (Cue::Select, None));
        let mut mix = vec![0.0; CHUNK];
        mix_chunk(&mut v, &c, &mut mix);
        // Both sound in the first chunk: the tick at full level, the opening fading.
        assert!(mix[0] > 1000.0 && mix[CHUNK - 1] < 2000.0);
        for _ in 0..3 {
            mix_chunk(&mut v, &c, &mut mix);
        }
        assert_eq!(v.iter().map(|v| v.cue).collect::<Vec<_>>(), vec![Cue::Select], "the faded opening is gone");
    }

    #[test]
    fn stop_fades_everything_out() {
        let c = clips();
        let mut v = Vec::new();
        handle(Msg::Play(Cue::Saved), &mut v, &c);
        handle(Msg::Stop, &mut v, &c);
        let mut mix = vec![0.0; CHUNK];
        for _ in 0..4 {
            mix_chunk(&mut v, &c, &mut mix);
        }
        assert!(v.is_empty());
    }

    #[test]
    fn other_formats_are_ignored() {
        assert!(decode(b"").is_empty());
        assert!(decode(b"RIFF\0\0\0\0WAVEdata\x02\0\0\0\x01\x02").is_empty());
    }

    /// Plays real audio: run with PULSE_SINK naming a test sink and record
    /// its monitor. Timeline: First in full (0–1.47 s), Later from 1.7 s
    /// replaced by Quick at 2.0 s (30 ms fade), Later from 2.6 s stopped at
    /// 2.9 s (30 ms fade).
    #[test]
    #[ignore = "plays audio"]
    fn plays_replaces_and_fades() {
        use std::time::Duration;
        let s = Sound::start(1.0);
        std::thread::sleep(Duration::from_millis(200));
        let at = std::time::Instant::now();
        let wait = |ms: u64| std::thread::sleep(Duration::from_millis(ms).saturating_sub(at.elapsed()));
        s.play(Cue::First);
        wait(1_700);
        s.play(Cue::Later);
        wait(2_000);
        s.play(Cue::Quick);
        wait(2_600);
        s.play(Cue::Later);
        wait(2_900);
        s.stop();
        wait(3_300);
    }

    /// Plays real audio (see above). The opening sound from 0 s; at 0.3 s a
    /// click ends the ripple (stop) and selects a key: the opening fades over
    /// 30 ms while the tick plays at once. Then rapid ticks every 10 ms from
    /// 1 s (only some sound), and a saved tone at 1.5 s.
    #[test]
    #[ignore = "plays audio"]
    fn ticks_interrupt_and_never_stack() {
        use std::time::Duration;
        let s = Sound::start(1.0);
        std::thread::sleep(Duration::from_millis(200));
        let at = std::time::Instant::now();
        let wait = |ms: u64| std::thread::sleep(Duration::from_millis(ms).saturating_sub(at.elapsed()));
        s.play(Cue::Later);
        wait(300);
        s.stop();
        s.play(Cue::Select);
        for i in 0..20 {
            wait(1_000 + i * 10);
            s.play(if i % 2 == 0 { Cue::Deselect } else { Cue::Select });
        }
        wait(1_500);
        s.play(Cue::Saved);
        wait(2_000);
    }

    #[test]
    fn volume_is_bounded() {
        assert_eq!(gain_for(-1.0), 0.0);
        assert_eq!(gain_for(2.0), 1.0);
        assert_eq!(gain_for(0.5), 0.25);
    }
}
